import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const MODEL_MAP_PATH = resolve(dirname(fileURLToPath(import.meta.url)), '../../config/model-map.json');

const MODEL_NOT_FOUND_PATTERNS = [
  /Model not found/i,
  /model.*not.*found/i,
];

export function resolveOpencodeModel(tier) {
  if (tier === undefined || tier === null) {
    return undefined;
  }

  try {
    const parsed = JSON.parse(readFileSync(MODEL_MAP_PATH, 'utf8'));
    const config = parsed?.opencode;
    if (!config || typeof config !== 'object' || Array.isArray(config)) {
      return undefined;
    }
    return config[tier];
  } catch {
    return undefined;
  }
}

export function createBaseSummary() {
  return {
    success: false,
    exitCode: null,
    sessionID: undefined,
    filesRead: [],
    filesModified: [],
    commandsExecuted: [],
    errors: [],
    modelErrors: [],
    finalMessages: [],
    tokenUsage: {
      input: 0,
      output: 0,
      total: 0,
      reasoning: 0,
      cache: { write: 0, read: 0 },
    },
    durationMs: 0,
    stderr: undefined,
  };
}

function classifyOpencodeErrorEvent(event) {
  const errorName = event.error?.name;
  const errorData = event.error?.data || {};

  if (errorName === 'APIError') {
    const statusCode = errorData.statusCode;
    if (statusCode === 401 || statusCode === 403) {
      return {
        class: 'auth_error',
        name: errorName,
        message: errorData.message,
        statusCode,
        isRetryable: errorData.isRetryable,
      };
    }
    if (statusCode === 429) {
      return {
        class: 'rate_limited',
        name: errorName,
        message: errorData.message,
        statusCode,
        isRetryable: errorData.isRetryable,
      };
    }
    if (typeof statusCode === 'number' && statusCode >= 500) {
      return {
        class: 'network_error',
        name: errorName,
        message: errorData.message,
        statusCode,
      };
    }
    if (errorData.isRetryable === false) {
      return {
        class: 'auth_error',
        name: errorName,
        message: errorData.message,
        statusCode,
        isRetryable: false,
      };
    }
  }

  const message = errorData.message || '';
  const isModelNotFound = errorData.code === 'model_not_found'
    || MODEL_NOT_FOUND_PATTERNS.some((p) => p.test(message));
  if (isModelNotFound) {
    return {
      class: 'model_unavailable',
      name: errorName || 'UnknownError',
      message,
    };
  }

  return {
    class: 'unknown',
    name: errorName || 'UnknownError',
    message,
  };
}

export function createOpencodeAdaptor() {
  const summary = createBaseSummary();

  return {
    push(event) {
      if (!event || typeof event !== 'object') {
        return;
      }

      if (event.sessionID !== undefined && summary.sessionID === undefined) {
        summary.sessionID = event.sessionID;
      }

      if (event.type === 'error' && event.error) {
        summary.modelErrors.push(classifyOpencodeErrorEvent(event));
        return;
      }

      const part = event.part;
      if (!part || typeof part !== 'object') {
        return;
      }

      if (event.type === 'tool_use' && part.type === 'tool') {
        const state = part.state && typeof part.state === 'object' ? part.state : {};
        const input = state.input && typeof state.input === 'object' ? state.input : {};
        const status = typeof state.status === 'string' ? state.status : undefined;

        if (part.tool === 'bash' && (status === 'completed' || status === 'error')) {
          const command = { command: input.command ?? '', status };
          if (state.output !== undefined) {
            command.output = state.output;
          }
          summary.commandsExecuted.push(command);
        }

        if (status === 'error') {
          summary.errors.push({
            tool: part.tool ?? 'unknown',
            callID: part.callID ?? null,
            error: state.error ?? 'unknown_error',
            context: Object.keys(input).length > 0 ? input : undefined,
          });
          return;
        }

        if (status !== 'completed') {
          return;
        }

        if (part.tool === 'read') {
          summary.filesRead.push({ path: input.filePath ?? null, status });
        }

        if (part.tool === 'edit' || part.tool === 'write') {
          summary.filesModified.push({ path: input.filePath ?? null, operation: part.tool });
        }

        return;
      }

      if (event.type === 'text' && typeof part.text === 'string') {
        summary.finalMessages.push(part.text);
        return;
      }

      if (event.type === 'step_finish' && part.tokens && typeof part.tokens === 'object') {
        const usage = part.tokens;
        const cache = usage.cache && typeof usage.cache === 'object' ? usage.cache : {};
        summary.tokenUsage = {
          input: Number(usage.input) || 0,
          output: Number(usage.output) || 0,
          total: Number(usage.total) || 0,
          reasoning: Number(usage.reasoning) || 0,
          cache: {
            write: Number(cache.write) || 0,
            read: Number(cache.read) || 0,
          },
        };
      }
    },
    getSummary() {
      return summary;
    },
    resolveModel(tier) {
      return resolveOpencodeModel(tier);
    },
    classifyStderr() {
      return null;
    },
  };
}

import { createBaseSummary } from './opencode.mjs';
import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const MODEL_MAP_PATH = resolve(dirname(fileURLToPath(import.meta.url)), '../../config/model-map.json');

const NETWORK_ERROR_PATTERNS = [
  /\bECONNREFUSED\b/,
  /\bETIMEDOUT\b/,
  /\bECONNRESET\b/,
  /\bEAI_AGAIN\b/,
  /\bunavailable\b/i,
];

const MODEL_UNAVAILABLE_PATTERNS = [
  /Cannot use this model/i,
  /model.*not.*available/i,
];

const AUTH_ERROR_PATTERNS = [
  /unauthorized/i,
  /forbidden/i,
  /invalid.*api.*key/i,
  /authentication.*failed/i,
];

export function resolveCursorModel(tier) {
  if (tier === undefined || tier === null) {
    return undefined;
  }

  try {
    const parsed = JSON.parse(readFileSync(MODEL_MAP_PATH, 'utf8'));
    const config = parsed?.cursor;
    if (!config || typeof config !== 'object' || Array.isArray(config)) {
      return undefined;
    }
    return config[tier];
  } catch {
    return undefined;
  }
}

export function classifyCursorStderr(stderr) {
  if (typeof stderr !== 'string' || stderr.length === 0) {
    return null;
  }
  if (AUTH_ERROR_PATTERNS.some((p) => p.test(stderr))) {
    return { class: 'auth_error', message: stderr.trim() };
  }
  if (MODEL_UNAVAILABLE_PATTERNS.some((p) => p.test(stderr))) {
    return { class: 'model_unavailable', message: stderr.trim() };
  }
  if (NETWORK_ERROR_PATTERNS.some((p) => p.test(stderr))) {
    return { class: 'network_error', message: stderr.trim() };
  }
  return null;
}

function getToolName(toolCall) {
  if (!toolCall || typeof toolCall !== 'object') {
    return 'unknown';
  }
  return Object.keys(toolCall).find((k) => k.endsWith('ToolCall')) ?? 'unknown';
}

function getToolData(toolCall, toolName) {
  if (!toolCall || typeof toolCall !== 'object') {
    return {};
  }
  return toolCall[toolName] ?? {};
}

export function createCursorAdaptor() {
  const summary = createBaseSummary();

  return {
    push(event) {
      if (!event || typeof event !== 'object') {
        return;
      }

      if (typeof event.sessionID === 'string' && summary.sessionID === undefined) {
        summary.sessionID = event.sessionID;
      }

      if (event.type === 'tool_call' && event.subtype === 'completed') {
        const toolCall = event.tool_call ?? {};
        const toolName = getToolName(toolCall);
        const toolData = getToolData(toolCall, toolName);
        const args = toolData.args ?? {};
        const result = toolData.result ?? {};

        if (toolName === 'readToolCall' && result.success) {
          summary.filesRead.push({ path: args.path ?? null, status: 'completed' });
        }

        if (toolName === 'editToolCall' && result.success) {
          summary.filesModified.push({ path: args.path ?? null, operation: 'edit' });
        }

        if (toolName === 'shellToolCall' && result.success) {
          summary.commandsExecuted.push({ command: args.command ?? '', status: 'completed' });
        }

        if (!result.success) {
          summary.errors.push({
            tool: toolName,
            error: result.error ?? 'unknown_error',
            context: Object.keys(args).length > 0 ? args : undefined,
          });
        }

        return;
      }

      if (event.type === 'assistant') {
        const content = Array.isArray(event.message?.content) ? event.message.content : [];
        for (const item of content) {
          if (item?.type === 'text' && typeof item.text === 'string') {
            summary.finalMessages.push(item.text);
          }
        }
        return;
      }

      if (event.type === 'result' && event.usage && typeof event.usage === 'object') {
        const usage = event.usage;
        summary.tokenUsage = {
          input: Number(usage.inputTokens) || 0,
          output: Number(usage.outputTokens) || 0,
          total: (Number(usage.inputTokens) || 0) + (Number(usage.outputTokens) || 0),
          reasoning: 0,
          cache: {
            write: Number(usage.cacheWriteTokens) || 0,
            read: Number(usage.cacheReadTokens) || 0,
          },
        };
      }
    },
    getSummary() {
      return summary;
    },
    resolveModel(tier) {
      return resolveCursorModel(tier);
    },
    classifyStderr(stderr) {
      const classified = classifyCursorStderr(stderr);
      if (classified) {
        summary.modelErrors.push(classified);
      }
      return classified;
    },
  };
}

import { fstatSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runCompanion as defaultRunCompanion } from './lib/runner.mjs';

export function isDirectExecution(moduleUrl, argv1, cwd = process.cwd()) {
  if (!argv1) {
    return false;
  }

  return moduleUrl === pathToFileURL(resolve(cwd, argv1)).href;
}

function stdinHasData() {
  try {
    const stat = fstatSync(0);
    return stat.isFIFO() || stat.isFile();
  } catch {
    return false;
  }
}

export function parseRunArguments(args) {
  const result = {
    prompt: undefined,
    agent: undefined,
    modelTier: undefined,
    dryRun: false,
  };

  for (let index = 0; index < args.length; index += 1) {
    const current = args[index];

    if (current === '--agent') {
      result.agent = args[index + 1];
      index += 1;
      continue;
    }

    if (current === '--model') {
      result.modelTier = args[index + 1];
      index += 1;
      continue;
    }

    if (current === '--dry-run') {
      result.dryRun = true;
      continue;
    }

    if (result.prompt === undefined) {
      result.prompt = current;
    }
  }

  return result;
}

async function readStdin() {
  const chunks = [];
  for await (const chunk of process.stdin) {
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString('utf-8').trimEnd();
}

export async function main(argv, deps = {}) {
  const [command, ...args] = argv;
  const exit = deps.exit ?? process.exit;
  const stdoutWrite = deps.stdoutWrite ?? ((chunk) => process.stdout.write(chunk));

  if (command === 'models') {
    const modelsLib = await import('./lib/models.mjs');

    if (args.includes('--list')) {
      const result = await (deps.listModels ?? modelsLib.listModels)();
      stdoutWrite(`${JSON.stringify(result)}\n`);
      exit(0);
      return 0;
    }

    if (args.includes('--set')) {
      try {
        const config = JSON.parse(await readStdin());
        const result = (deps.setModels ?? modelsLib.setModels)(config);
        const code = result.success ? 0 : 1;
        stdoutWrite(`${JSON.stringify(result)}\n`);
        exit(code);
        return code;
      } catch (error) {
        const result = {
          type: 'done',
          success: false,
          error: `Invalid JSON: ${error.message}`,
        };
        stdoutWrite(`${JSON.stringify(result)}\n`);
        exit(1);
        return 1;
      }
    }

    throw new Error('Unsupported models subcommand');
  }

  if (command !== 'run') {
    throw new Error(`Unsupported subcommand: ${command}`);
  }

  const parsed = parseRunArguments(args);

  const runCompanionFn = deps.runCompanion
    ?? (deps.runOpencode
      ? (_agentType, prompt, options) => deps.runOpencode(prompt, options)
      : defaultRunCompanion);
  let prompt = parsed.prompt;
  const hasStdinData = deps.stdinHasData ?? stdinHasData;
  if (prompt === undefined && hasStdinData()) {
    prompt = await readStdin();
  }

  const result = await runCompanionFn(parsed.agent ?? 'opencode', prompt, {
    agent: parsed.agent,
    modelTier: parsed.modelTier,
    dryRun: parsed.dryRun,
  });
  const code = result.success ? 0 : 1;

  exit(code);

  return code;
}

if (isDirectExecution(import.meta.url, process.argv[1])) {
  await main(process.argv.slice(2));
}

